INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 5, 'theory', 'Quiz: loops');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 0, 'How does a for loop differ from a while loop?', '["Not at all, they are synonyms", "for means “for each element of”, while means “as long as the condition is true”", "while works only with numbers", "for is always faster"]', 1, 'for is for when we know what we go over; while is for repeating until some event happens.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 1, 'How many times will the body run in: for i in range(3)?', '["2", "3", "4", "Endlessly"]', 1, 'range(3) gives the numbers 0, 1, 2: three passes. The right bound is not included.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 2, 'What does break do inside a loop?', '["Skips one pass", "Exits the loop immediately", "Restarts the loop from the beginning", "Stops the whole program"]', 1, 'break interrupts the whole loop: execution continues after it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 3, 'What does continue do?', '["Exits the loop", "Skips the rest of the body and goes to the next pass", "Starts the loop over with a new condition", "Nothing: it is a placeholder"]', 1, 'continue skips only the current pass, and the loop goes on.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 5, 4, 'How many numbers will for i in range(2, 10, 3) print?', '["2", "3", "4", "8"]', 1, 'Step three from two: 2, 5, 8; next would be 11, and the bound 10 is already passed. Three numbers in total.');
